ght 6 hex digits          swpb      r1          andi      r1,000FF          clr       r0          rt.shr7dg    mov       r0,r1               shift right 7 hex digits          srl       r1,12          clr       r0          rt..sgnbit    data      08000               sign bittopdgt    data      0f000               top digittopdiv    data      01e00               top digit, scaled for divisionrndbit    data      00080               test bit for round up... ********************************************************************. *                     BUFFER MANAGEMENT PRIMITIVES                 *. ********************************************************************..         Insert buffer at queue end..         LI        R8,<buffer>.         LI        R9,<queue>.         BLWP      INSERT$.         <return>.INSRT*    limi      0          mov       2*r8(r13),r8          mov       2*r9(r13),r9          mov       *r9,*r8          mov       *r9,r11          mov       r8,2(r11)          mov       r9,2(r8)          mov       r8,*r9          rtwp      ..         Insert buffer at queue start..         LI        R8,<buffer>.         LI        R9,<queue>.         BLWP      PUSH$.         <return>.PUSH*     limi      0          mov       2*r8(r13),r8          mov       2*r9(r13),r9          mov       2(r9),r11          mov       r11,2(r8)          mov       r8,*r11          mov       r9,*r8          mov       r8,2(r9)          rtwp      ..         Remove next buffer from queue..         LI        R9,<queue>.         BLWP      REMOVE$.         <return>  R8=buffer.REMOV*    limi      0          mov       2*r9(r13),r9          mov       2(r9),r8          mov       2(r8),r11          mov       r11,2(r9)          mov       r9,*r11          mov       r8,2*r8(r13)          rtwp      ..         Initialise queue links.         LI        R9,<queue>.         BLWP      INITQ$.         <return>.INITQ*    limi      0      