           mov       *r12,r11          jne       jlb8    jlb12     mov       r10,6(r12)          mov       4(r10),4(r12)          mov       r12,4(r10)          mov       4(r12),r9          mov       r12,6(r9)          mov       r12,r11jlb8      s         2(r12),r12          mov       *r12,r9          jne       jlb9              mov       2(r12),r9          jlt       jlb10             mov       4(r12),r9          mov       6(r12),r8          mov       r9,4(r8)          mov       r8,6(r9)          a         2(r12),r12jlb10     mov       r11,*r12          s         r11,r12          mov       r12,2(r11)jlb11     rtwp   exit$     equ       2.jlb7      jsys      ex2ex2       byte      exit$,0           data      00011.jlb9      jsys      ex3ex3       byte      exit$,0           data      00012..         Add space to buffer pool..         LI        R0,<length of area to add>.         LI        R1,<address of area to add>.         BLWP      BEXP$.         <return>.BEXP*     limi      0          mov       0(r13),r11          mov       2(r13),r12          andi      r11,0FFFE          ai        r12,1          andi      r12,0FFFE          ci        r11,0E          jl        jlb11             clr       *r12          ai        r11,0FFFC          mov       r11,2(r12)          a         r12,r11          clr       *r11+          seto      *r11          neg       2(r12)          jmp       jlb12   ... ********************************************************************. *                     TERMINAL HANDLER                             *. ********************************************************************...         LI        R0,length.         LI        R1,startoftext.         BL        prtstr.prtstr    pshr      r11                 print message          mov       cetogg,r11          do we want to send to printer          jeq       noprnt              -> no.          mov       r0,saver0          mov       r1,saver1          mov       r5,saver5          mov       r6,saver6          mov       r8,saver8          mov       r0,r6               length          mov       r1,r5               start          li        r1,w$          li        r8,UT$PR1          bl        PIOPRT          mov       saver0,r0          mov       saver1,r1          mov       saver5,r5          mov       saver6,r6          mov       saver8,r8noprnt    dec       r0                  length-1          jlt       finish              finished          movb      *r1+,r2             no, get another char          srl       r2,8                rigth adjust          bl        echcook             echo cooked          jmp       noprntfinish    li        r2,0D               CR          bl        echcook             echo cooked          mov       cstogg,r0           ^S active?          jne       waitcs              yes go and wait for anothergohome    popjwaitcs              bl        termrd          ci        r2,013              is it ^S          jne       waitcs              no,          clr       cstogg              yes, clear it          jmp       gohome              and get out of here.. Read a 'cooked' line from the console terminal.rdline    pshr      r11                 main subbroutine entry          mov       cetogg,cetog2	save print ^E togglerdrtype   bl        retype              retype outbuf & enter loop          clr       cetog2. 2nd entry into realine: store into input buffer.rdlloop   clr       r6                  enter realine loop          li        r7,inpbuf           set up input buffer	  nxtchr    bl        termrd              read char from console terminal          ci        r2,01B              ESC          jeq       escrou          ci        r2,0D               CR = ^M          jeq       contrm          ci        r2,018              ^X  delete line          jeq       contrx          ci        r2,08               ^H  backspace          jeq       contrh          ci        r2,012              ^R  retype line          jeq       contrr          ci        r2,017              ^W  delete word          jeq       contrw          ci        r6,80               max line length?          jeq       nxtchr              ignore further content          bl        echcook             echo char cookedjlb0DD    swpb      r2                  place in input buffer          movb      r2,*r7+          inc       r6          jmp       nxtchr              and continue. ESC = next char is raw, echoed rawescrou    bl        TRSTAT              wait for next char          jeq       escrou          bl        TREADC          ci        r6,050          jeq       nxtchr          bl        echoraw             echo char as 'raw'          jmp       jlb0DD. ^M = CR = finish line & returncontrm    bl        echcook             echo cooked          mov       cetogg,r0           copy to printer?          jeq       jlb0DE              no ->          swpb      r2                  place in buffer          movb      r2,*r7          mov       r6,saver6          mov       r8,saver8          mov       r5,saver5          li        r5,inpbuf           input buffer          li        r1,w$               set w$          li        r8,UT$PR1           call printer driver          inc       r6          bl        PIOPRT          mov       saver5,r5          mov       saver8,r8          mov       saver6,r6           drop from buffer againjlb0DE    li        r7,inpbuf           reset r7 to input buffer          popj                          return. ^X = delete linecontrx    li        r0,CRTCON           glass terminal ?                jne       jlb0DF              -> yes          bl        echcook             echo cooked          li        r2,0D               load CR          bl        echcook             echo cooked          jmp       rdrtype             resume line input          jlb0DF    dec       r6                  everything rubbed?          jlt       rdlloop             yes -> resume          dec       r7          bl        rubout              rub out last char          jmp       jlb0DF.. ^H = backspacecontrh    dec       r6                  at start of line ?          jlt       rdlloop             -> yes, ignore          dec       r7          bl        rubout              rubout one char          jmp       nxtchr              resume input loop.. ^R = retype linecontrr    bl        echcook             echo cooked          li        r2,0D               load CR          bl        echcook             echo cooked          bl        retype              retype line          li        r1,inpbuf           begin of bufferjlb0E1    c         r1,r7          jeq       nxtchr              done -> resume input loop          movb      *r1+,r2             echo one char          srl       r2,8          bl        echcook          jmp       jlb0E1              until done.. ^W = delete wordcontrw    dec       r6                  if at start line, resume loop          jlt       rdlloop          dec       r7          bl        rubout              rubout character on screen          bl        isword              is it a word char (letter, digit, $)?          jne       contrw              loop until we hit a wordjlb0E3    dec       r6                  at start?          jlt       rdlloop             yes -> resume loop          dec       r7                  backup one char          bl        isword              check its type          jne       jlb0E2              not a word, done          bl        rubout              rubout on screen          jmp       jlb0E3              until all donejlb0E2    inc       r6                  restore look ahead char          inc       r7          b         nxtchr              resume loop.. check if character is a word characterisword    movb      *r7,r0              inspect character          srl       r0,8          ci        r0,'$'              $ is part of word          jeq       jlb0E4          ci        r0,060              make lower case          jlt       jlb0E5          andi      r0,05Fjlb0E5    ci        r0,'0'              char < '0' ?          jlt       jlb0E6              not part of a word          ci        r0,'9'              char > '9'          jgt       jlb0E7              check lettersjlb0E4    c         r0,r0               set EQ flag & returnjlb0E6    rtjlb0E7    ci        r0,'A'              char < 'A' ?          jlt       jlb0E6              not part of a word          ci        r0,'Z'              char > 'Z' ?          jgt       jlb0E6              not part of a word          jmp       jlb0E4              is ok, return with EQ set... rubout screen character (two for control)rubout    pshr      r11          bl        rubone              rubout          movb      *r7,r0              get char          srl       r0,8          ci        r0,' '              was it a ctrl?          jlt       jlb0E8              yes ->jlb0E9    popjjlb0E8    bl        rubone              rubout ^ as well          jmp       jlb0E9              done.. rubout single characterrubone    pshr      r11          li        r2,08               backspace          bl        echoraw             echo raw          li        r2,' '              space          bl        echoraw             echo raw          li        r2,08               backspace          bl        echoraw             echo raw          popj.. retype output buffer to console / printer.retype    pshr      r11          li        r1,outbuf           go through output bufferjlb0EB    movb      *r1+,r2          srl       r2,8          ci        r2,07F              end of buffer?          jeq       jlb0EA              yes -> done          bl        echoraw             echo raw to console          jmp       jlb0EB              and loopjlb0EA    mov       cetog2,r0           copy to printer was on?          jeq       jlb0EC              no ->          mov       r5,saver5           print prompt as well          mov       r6,saver6          mov       r8,saver8          li        r6,outbufjlb0ED    cb        *r6+,eoomrk         find end of output marker          jne       jlb0ED          li        r5,outbuf          s         r5,r6          dec       r6          jeq       jlb0EE              -> prompt done          li        r1,w$          li        r8,UT$PR1          bl        PIOPRTjlb0EE    mov       saver8,r8          mov       saver6,r6          mov       saver5,r5jlb0EC    popj. echo character in 'cooked mode'.echcook   pshr      r11                 save our return          ci        r2,' '              ch is before space?          jlt       contrl              yes -> control char          bl        echorawgoback    popj                          returncontrl    ci        r2,0D               CR?          jeq       crchar          pshr      r2                  save original char          li        r2,05E              "^"          bl        echoraw          popr      r2                  get char back          ai        r2,64               make capital ascii          bl        echoraw          ai        r2,-64              make original char          jmp       goback	  crchar              bl        echoraw          li        r2,TCRDLY           does it need delay          jeq       nocrdl              no skip delaycrspin              pshr      r2                  save r2          li        r2,07F              dummy char          bl        echoraw          popr      r2                  get r2=delay count          dec       r2                  any more to go          jne       crspin              yes, once morenocrdl              li        r2,0A               line feed          bl        echoraw          li        r2,0D               <cr> give back sent char          jmp       goback.cbreak    li        r2,3                load ^C          bl        echcook             print on console          li        r2,0D               load CR          bl        echcook             print on console          clr       cstogg              clear output pause (^S)          mov       intvec,r11          resume at interrupt handler          rt.. print char in r2 to console and test for ^C, ^E and ^Sechoraw    pshr      r11          mov       is$raw,r11          check for raw mode          jne       jlb0F4              yes -> do raw (no buffering)          mov       r2,r3               check for ctl input          bl        TRSTAT              char available?          jeq       jlb0F5              no ->          bl        TREADC              get char from console driver          ci        r2,02               was it ^C ?   [PNR: changed to ^B]          jeq       cbreak              yes -> break          ci        r2,05               was it ^E ?          jne       jlb0F7                        inv       cetogg              toggle printer copyjlb0F7    ci        r2,013              was it ^S ?          jne       jlb0F5          seto      cstogg              set output pause (no toggle?)jlb0F5    mov       r3,r2               restore print charjlb0F4    bl        TWSTAT              wait for console ready          jeq       jlb0F4          bl        TWRITE              write to console          popj. read char from console terminal, check for ^C and ^.termrd    pshr      r11jlb0F8    bl        TRSTAT              wait for device ready          jeq       jlb0F8jlb0FA    bl        TREADC              read char          ci        r2,2                is it ^C ?  [PNR: changed to ^B]          jeq       cbreak              -> break          ci        r2,5                is it ^E ?          jne       jlb0F9              no -> done          inv       cetogg              toggle printer flag          jmp       jlb0F8              next charjlb0F9    popj                          return..INTCHK*   mov       r11,*r10+           check for ^C          bl        TRSTAT          jeq       jlb0F9          jmp       jlb0FA..eoomrk    data      07f00               end-of-output ("eoo") markeroutbuf    bss       80                  output bufferinpbuf    bss       82                  input bufferintvec    bss       2                   break vector (for ^C)cstogg    bss       2                   pause output (^S)cetogg    bss       2                   console echo to printer (^E)cetog2    bss       2                   copy of the above ??saver0    bss       2                   tmp for r0-r8saver1    bss       2saver5    bss       2saver6    bss       2saver8    bss       2          end       mstart.